// path: apps/web/src/app/(app)/transcript/detail/page.tsx
"use client";

import { fetchTranscript, type TranscriptItem } from "@/lib/transcript/api";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

function normalizeText(value: unknown) {
  return String(value ?? "").trim().toLowerCase();
}

function formatScore(value: number | null | undefined) {
  if (value === null || value === undefined) return "--";
  return Number.isInteger(value) ? String(value) : value.toFixed(2);
}

function getStatusLabel(status: string | null | undefined) {
  const s = normalizeText(status);
  if (s === "passed") return "Đạt";
  if (s === "failed") return "Chưa đạt";
  return "Chưa rõ";
}

export default function TranscriptDetailPage() {
  const searchParams = useSearchParams();

  const courseCode = searchParams.get("courseCode") || "";
  const classCode = searchParams.get("classCode") || "";
  const semester = searchParams.get("semester") || "";

  const [item, setItem] = useState<TranscriptItem | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function run() {
      setLoading(true);
      setError(null);

      try {
        const data = await fetchTranscript(semester || undefined);
        const found =
          data.items?.find(
            (x) =>
              x.courseCode === courseCode &&
              (x.classCode || "") === classCode &&
              x.semester === semester,
          ) || null;

        setItem(found);
      } catch (e) {
        setError(String((e as Error)?.message || e));
      } finally {
        setLoading(false);
      }
    }

    void run();
  }, [courseCode, classCode, semester]);

  const detailItems = useMemo(() => {
    return Array.isArray(item?.componentsBreakdown?.detailItems)
      ? item!.componentsBreakdown!.detailItems!
      : [];
  }, [item]);

  if (loading) {
    return (
      <div className="mx-auto max-w-5xl p-4 lg:p-6">
        <div className="app-card rounded-3xl p-6">
          Đang tải chi tiết môn học...
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="mx-auto max-w-5xl p-4 lg:p-6">
        <div className="app-card rounded-3xl p-6 text-red-400">{error}</div>
      </div>
    );
  }

  if (!item) {
    return (
      <div className="mx-auto max-w-5xl p-4 lg:p-6">
        <div className="app-card rounded-3xl p-6">
          Không tìm thấy dữ liệu chi tiết môn này.
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto w-full max-w-5xl p-4 lg:p-6">
      <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold">{item.courseName}</h1>
          <div className="mt-1 text-sm app-text-muted">
            {item.courseCode} • {item.classCode || "--"} • {item.semester}
          </div>
        </div>

        <Link
          href="/transcript"
          className="app-btn inline-flex rounded-2xl px-4 py-2 text-sm font-semibold"
        >
          Quay lại bảng điểm
        </Link>
      </div>

      <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1.7fr)_320px]">
        <div className="space-y-4">
          <div className="app-card rounded-3xl p-5">
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
              <div className="app-card-strong rounded-2xl p-4">
                <div className="text-xs uppercase app-text-muted">Điểm 10</div>
                <div className="mt-2 text-2xl font-bold">
                  {formatScore(item.score10)}
                </div>
              </div>

              <div className="app-card-strong rounded-2xl p-4">
                <div className="text-xs uppercase app-text-muted">Điểm chữ</div>
                <div className="mt-2 text-2xl font-bold">
                  {item.letter || "--"}
                </div>
              </div>

              <div className="app-card-strong rounded-2xl p-4">
                <div className="text-xs uppercase app-text-muted">GPA 4</div>
                <div className="mt-2 text-2xl font-bold">
                  {formatScore(item.gpa4)}
                </div>
              </div>

              <div className="app-card-strong rounded-2xl p-4">
                <div className="text-xs uppercase app-text-muted">
                  Tổng từ chi tiết
                </div>
                <div className="mt-2 text-2xl font-bold">
                  {formatScore(item.componentsBreakdown?.detailSummary?.totalScore10)}
                </div>
              </div>
            </div>
          </div>

          <div className="app-card rounded-3xl p-5">
            <div className="mb-4">
              <div className="text-xs uppercase tracking-wide app-text-muted">
                Cấu phần điểm
              </div>
              <h2 className="mt-1 text-lg font-bold">Bảng chi tiết</h2>
            </div>

            {detailItems.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-[var(--border-main)] px-4 py-5 app-text-muted">
                Môn này hiện chưa đồng bộ được cấu phần chi tiết.
              </div>
            ) : (
              <div className="overflow-hidden rounded-2xl border border-[var(--border-main)]">
                <div className="overflow-auto">
                  <table className="w-full min-w-[860px] text-sm">
                    <thead className="bg-[var(--bg-soft)] app-text-soft">
                      <tr className="text-left">
                        <th className="px-4 py-3">Cấu phần</th>
                        <th className="px-4 py-3">Điểm lần 1</th>
                        <th className="px-4 py-3">Điểm lần 2</th>
                        <th className="px-4 py-3">Thang điểm</th>
                        <th className="px-4 py-3">% điểm</th>
                        <th className="px-4 py-3">Điểm quy đổi</th>
                        <th className="px-4 py-3">% tối đa</th>
                      </tr>
                    </thead>
                    <tbody>
                      {detailItems.map((detail, index) => (
                        <tr
                          key={`${item.id}-${detail.componentLabel}-${index}`}
                          className="border-t border-[var(--border-main)]"
                        >
                          <td className="px-4 py-3 font-semibold">
                            {detail.componentLabel}
                          </td>
                          <td className="px-4 py-3">{formatScore(detail.score1)}</td>
                          <td className="px-4 py-3">{formatScore(detail.score2)}</td>
                          <td className="px-4 py-3">{formatScore(detail.scaleScore)}</td>
                          <td className="px-4 py-3">{formatScore(detail.weightPercent)}</td>
                          <td className="px-4 py-3">
                            {formatScore(detail.contributionScore)}
                          </td>
                          <td className="px-4 py-3">
                            {formatScore(detail.contributionMax)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-4">
          <div className="app-card rounded-3xl p-5">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              Thông tin học phần
            </div>

            <div className="mt-4 space-y-3 text-sm">
              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Mã môn</span>
                <span className="font-semibold">{item.courseCode}</span>
              </div>

              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Mã lớp</span>
                <span className="font-semibold">{item.classCode || "--"}</span>
              </div>

              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Tín chỉ</span>
                <span className="font-semibold">{item.credits}</span>
              </div>

              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Trạng thái</span>
                <span className="font-semibold">{getStatusLabel(item.status)}</span>
              </div>

              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Nguồn detail</span>
                <span className="font-semibold">
                  {item.componentsBreakdown?.detailUrl ? "MYDTU" : "--"}
                </span>
              </div>
            </div>
          </div>

          <div className="app-card rounded-3xl p-5">
            <div className="text-xs uppercase tracking-wide app-text-muted">
              Tóm tắt chi tiết
            </div>

            <div className="mt-4 space-y-3 text-sm">
              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Số cấu phần</span>
                <span className="font-semibold">{detailItems.length}</span>
              </div>

              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Tổng điểm chi tiết</span>
                <span className="font-semibold">
                  {formatScore(item.componentsBreakdown?.detailSummary?.totalScore10)}
                </span>
              </div>

              <div className="flex justify-between gap-4">
                <span className="app-text-muted">Tổng tỷ trọng</span>
                <span className="font-semibold">
                  {formatScore(item.componentsBreakdown?.detailSummary?.totalPercent)}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}